use std::fs
use std::collections::HashMap

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let p = line.split_whitespace()
        if p.len() == 0 { continue }
        let cmd = p[0]
        if cmd == "balance" {
            if p.len() < 2 { continue }
            let n = p[1]
            if acc.contains_key(n) {
                println("${acc[n]}")
            } else {
                println("error: unknown account ${n}")
            }
        } else if cmd == "open" {
            if p.len() < 3 { continue }
            let n = p[1]
            let amt: int = p[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(n) {
                println("error: duplicate account")
            } else {
                acc.insert(n, amt)
                println("ok")
            }
        } else if cmd == "deposit" || cmd == "withdraw" {
            if p.len() < 3 { continue }
            let n = p[1]
            let amt: int = p[2].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(n) {
                println("error: unknown account ${n}")
            } else if cmd == "deposit" {
                let b: int = acc[n]
                acc.insert(n, b + amt)
                println("ok")
            } else {
                let b: int = acc[n]
                if b < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(n, b - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" {
            if p.len() < 4 { continue }
            let f = p[1]
            let t = p[2]
            let amt: int = p[3].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(f) {
                println("error: unknown account ${f}")
            } else if !acc.contains_key(t) {
                println("error: unknown account ${t}")
            } else if f == t {
                println("error: same account")
            } else {
                let fb: int = acc[f]
                let tb: int = acc[t]
                if fb < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(f, fb - amt)
                    acc.insert(t, tb + amt)
                    println("ok")
                }
            }
        }
    }
    let mut names: Vec<string> = []
    for k in acc.keys() {
        names.push(k)
    }
    names.sort()
    for n in names {
        println("${n} ${acc[n]}")
    }
}

